insert into public.lift_blocks (name, notes, weeks, date_moves) select 'Winter Block 1', 'Block 1 = 11/23 - 12/14', 4, '[{"week": 1, "weekday": 4, "moved_to": "2026-11-27"}, {"week": 1, "weekday": 5, "moved_to": "2026-11-28"}]'::jsonb where not exists (select 1 from public.lift_blocks where name = 'Winter Block 1');
insert into public.block_days (block_id, weekday, label, focus, prep_id, warmup, sprints, notes) select (select id from public.lift_blocks where name = 'Winter Block 1'), 1, 'Lower Focus', 'lower', (select id from public.lift_preps where name = 'Movement Prep A'), 'Zercher BB Squat WU (2-3 sets) up to your working set weight', '["10/10: 1 x 90%, 2 x 95%", "15/10: 1 x 90%, 3 x 95%", "20/10: 1 x 90%, 3 x 95%", "5/10: 1 x 90%, 3 x 95%"]'::jsonb, 'You fight hard as hell to add 5lbs to your compound lifts each week. Acknowledge the RIR, and get after it.' where not exists (select 1 from public.block_days where block_id = (select id from public.lift_blocks where name = 'Winter Block 1') and weekday = 1);
