insert into public.block_assignments (block_id, person_id, start_date)
select (select id from public.lift_blocks where name = 'Winter Block 2'), p.id, '2026-12-21' from public.people p where p.active and not p.is_coach
on conflict (block_id, person_id, start_date) do nothing;

commit;

select b.name, (select count(*) from public.block_days d where d.block_id = b.id) as days,
  (select count(*) from public.block_exercises e join public.block_days d on d.id = e.block_day_id where d.block_id = b.id) as exercises,
  (select count(*) from public.block_assignments a where a.block_id = b.id) as athletes_assigned
from public.lift_blocks b order by b.name;